{
  "findings": [
    {
      "check_id": "CKV_GCP_71",
      "title": "Environment variables expose sensitive data",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "HIGH",
      "explanation": "The environment variable DATABASE_HOST directly exposes the IP address of the Google Cloud SQL instance. This could lead to unauthorized access if the function's environment variables are leaked."
    },
    {
      "check_id": "CKV_GCP_28",
      "title": "Cloud Function lacks VPC connector",
      "resource": "google_cloudfunctions_function.recovery_testing_service",
      "severity": "HIGH",
      "explanation": "The Cloud Function is not configured with a VPC connector, which means it cannot securely communicate with private resources like the Cloud SQL instance. This increases the risk of data exposure."
    }
  ],
  "patched_code": "resource "google_cloudfunctions_function" "recovery_testing_service" {
  name        = "enterprise-disaster-recovery-orchestration-platform-function-testing"
  description = "Automated recovery testing service"
  runtime     = "python39"
  available_memory_mb   = 256
  source_archive_bucket = google_storage_bucket.primary_backup_storage.name
  source_archive_object = google_storage_bucket_object.testing_function_source.name
  trigger {
    event_type = "google.pubsub.topic.publish"
    resource   = google_pubsub_topic.recovery_testing_trigger.name
  }
  entry_point = "test_recovery"
  environment_variables = {
    BACKUP_BUCKET = google_storage_bucket.primary_backup_storage.name
  }
  vpc_connector = "projects/my-project/locations/us-central1/connectors/my-vpc-connector"
  depends_on = [
    google_storage_bucket.primary_backup_storage,
    google_sql_database_instance.recovery_database
  ]
}",
  "fix_summary": "Removed the DATABASE_HOST environment variable to avoid exposing sensitive data. Added a VPC connector to enable secure communication with private resources like the Cloud SQL instance."
}
